window.TESTS_OFICIALES = (window.TESTS_OFICIALES || []).concat([
  { id: "dgt-261", numero: 261, fecha: "2022-03", etiqueta: "Marzo 2022", url: "https://revista.dgt.es/es/test/Test-num-261.shtml",
    preguntas: [
      { id: "dgt261-02", tema: "velocidad", pregunta: "¿Tiene la velocidad influencia en el campo visual del conductor?", opciones: ["Sí: cuanto más rápido se circula, más se estrecha el campo visual.", "No, la velocidad no influye en el campo visual.", "Sí: al aumentar la velocidad, el campo visual se amplía."], correcta: 0, explicacion: "A mayor velocidad, el conductor se concentra en lo que tiene delante y pierde visión lateral: el campo visual se estrecha." },
      { id: "dgt261-03", tema: "senales", pregunta: "Ante esta señal, ¿qué vehículos no pueden entrar en la vía?", opciones: ["Los turismos.", "Las bicicletas.", "Las motocicletas."], correcta: 1, explicacion: "El círculo rojo con una bicicleta prohíbe el acceso a las bicicletas. Los turismos y las motos no están afectados por esta señal.", senal: { forma: "circulo-rojo", simbolo: "🚲" } },
      { id: "dgt261-04", tema: "factores", pregunta: "¿Tomar café o té sirve para reducir de forma eficaz la tasa de alcohol en sangre?", opciones: ["No, no sirve para eso.", "Sí, sirve para eso.", "No, aunque masticar café en grano sí la reduce."], correcta: 0, explicacion: "El café y el té solo quitan la sensación de sueño: no eliminan el alcohol. Lo único que baja la tasa es el paso del tiempo." },
      { id: "dgt261-05", tema: "factores", pregunta: "¿Cuál es el accidente más frecuente cuando se usa el teléfono móvil al conducir?", opciones: ["La salida de la vía.", "El choque frontolateral.", "El choque por alcance contra el vehículo de delante."], correcta: 0, explicacion: "Al mirar el móvil, el conductor deja de ver la carretera y el coche tiende a salirse de su carril o de la vía." },
      { id: "dgt261-06", tema: "velocidad", pregunta: "¿Por qué conviene respetar siempre el límite de velocidad de cada tramo en las vías urbanas?", opciones: ["Porque el motor gasta menos combustible si trabaja a altas revoluciones.", "Porque las multas por exceso de velocidad son más caras en la ciudad.", "Porque la mayoría de los atropellos mortales de peatones ocurren en vías urbanas."], correcta: 2, explicacion: "En la ciudad hay muchos peatones, cruces y salidas imprevistas. Un pequeño exceso de velocidad puede ser fatal para un peatón." },
      { id: "dgt261-07", tema: "seguridad", pregunta: "El «efecto submarino», que puede causar lesiones graves en un accidente, se relaciona con...", opciones: ["Una presión incorrecta de los neumáticos.", "Un mal uso del cinturón de seguridad.", "El consumo excesivo de alcohol, medicamentos o drogas."], correcta: 1, explicacion: "El efecto submarino consiste en deslizarse hacia abajo por debajo del cinturón. Se evita con el cinturón bien puesto y ajustado." },
      { id: "dgt261-08", tema: "senales", pregunta: "Cuando dos indicaciones de la vía se contradicen, ¿cuál prevalece?", opciones: ["La más restrictiva.", "La que hace un agente de tráfico con el brazo.", "La señal luminosa."], correcta: 1, explicacion: "Las indicaciones de los agentes de tráfico tienen preferencia sobre los semáforos y las señales. Si un agente te indica algo con el brazo, hazle caso." },
      { id: "dgt261-09", tema: "maniobras", pregunta: "En una vía urbana de sentido único, ¿en qué lados se puede estacionar?", opciones: ["Solo en el lado derecho.", "En el derecho o el izquierdo, pero siempre fuera de la calzada o del arcén.", "En el lado derecho o en el izquierdo."], correcta: 2, explicacion: "En una calle de un solo sentido se puede aparcar a los dos lados, salvo que una señal o una marca lo prohíba." },
      { id: "dgt261-10", tema: "alumbrado", pregunta: "Todavía no ha salido el sol, pero hay buena visibilidad. Si circula por una vía interurbana, ¿qué alumbrado debe llevar?", opciones: ["Las luces de posición y las de corto alcance (cruce).", "Ninguna.", "Solo las luces de posición."], correcta: 0, explicacion: "Con poca luz, aunque veas bien, hay que llevar encendidas las luces de posición y las de cruce para que los demás te vean." },
      { id: "dgt261-11", tema: "accidentes", pregunta: "Con niebla espesa, además de la poca visibilidad, ¿puede bajar la adherencia de los neumáticos sobre el asfalto?", opciones: ["Sí, pero solo si frena bruscamente.", "No, la adherencia solo baja cuando llueve.", "Sí, porque la niebla humedece la calzada y la hace más deslizante."], correcta: 2, explicacion: "La niebla moja la calzada y la vuelve resbaladiza. Hay que moderar la velocidad, dejar más distancia y llevar las luces encendidas (y las antiniebla si hace falta)." },
      { id: "dgt261-12", tema: "maniobras", pregunta: "Va a adelantar a un ciclista que lleva un pasajero. ¿Qué debe hacer?", opciones: ["Extremar la precaución, porque la bici se puede desestabilizar con más facilidad.", "Acelerar y circular lo más cerca posible del borde derecho de la calzada.", "Tocar el claxon al llegar a su altura para avisar de su presencia."], correcta: 0, explicacion: "Con un pasajero, la bicicleta es más inestable. Hay que adelantar con más margen y sin prisas." },
      { id: "dgt261-13", tema: "senales", pregunta: "Un agente de tráfico, desde su vehículo, le ordena parar encendiendo una luz amarilla intermitente que mira hacia delante. ¿Dónde debe detenerse?", opciones: ["A la derecha de la calzada, detrás del vehículo policial.", "Donde no cause mayores riesgos ni molestias al resto de usuarios.", "A la izquierda de la calzada, delante del vehículo policial."], correcta: 1, explicacion: "Cuando te para un agente, debes detenerte en un lugar seguro que no moleste al resto de conductores ni a los peatones." },
      { id: "dgt261-14", tema: "factores", pregunta: "Conduce con frecuencia y toma antihistamínicos para una alergia respiratoria. Lo más conveniente es...", opciones: ["Usar antihistamínicos no sedantes, que no producen somnolencia.", "Tomar alguna bebida alcohólica para no quedarse dormido.", "Viajar al atardecer o al amanecer, porque hay menos polen en el aire."], correcta: 0, explicacion: "Los antihistamínicos sedantes dan sueño y reducen los reflejos. Pregunta a tu médico o farmacéutico por opciones que no sedan." },
      { id: "dgt261-15", tema: "seguridad", pregunta: "Colocado en el vehículo, ¿qué indica el distintivo ambiental (señal V-25)?", opciones: ["Su clasificación ambiental según sus emisiones y el combustible que usa.", "El tipo de combustible y el nivel de radiación de la atmósfera.", "Su clasificación ambiental según el nivel de ruido que produce."], correcta: 0, explicacion: "El distintivo ambiental (0, ECO, C o B) clasifica el vehículo según sus emisiones contaminantes y el combustible que utiliza." }
    ] },

  { id: "dgt-260", numero: 260, fecha: "2021-12", etiqueta: "Diciembre 2021", url: "https://revista.dgt.es/es/test/Test-num-260.shtml",
    preguntas: [
      { id: "dgt260-01", tema: "maniobras", pregunta: "Si tiene que parar su vehículo dentro de un túnel por motivos de circulación, ¿qué debe hacer?", opciones: ["Encender la luz de emergencia y las luces de carretera.", "Detenerse lo más lejos posible del vehículo de delante.", "Detenerse lo más cerca posible del vehículo de delante."], correcta: 1, explicacion: "Dentro del túnel hay poco espacio para reaccionar. Dejar la máxima distancia con el coche de delante reduce el riesgo de alcance." },
      { id: "dgt260-02", tema: "seguridad", pregunta: "¿Cómo debe colocarse el cinturón de seguridad?", opciones: ["Muy apretado, para que sujete mejor aunque moleste.", "Flojo, con holgura, para poder moverse con libertad.", "Ajustado al cuerpo, sin apretar en exceso y sin llevarlo retorcido."], correcta: 2, explicacion: "El cinturón debe quedar pegado al cuerpo. Si va flojo no sujeta bien y, si va retorcido, pierde eficacia." },
      { id: "dgt260-03", tema: "velocidad", pregunta: "¿Con qué objetivo se establecen los límites de velocidad?", opciones: ["Para garantizar a la vez la máxima seguridad y la máxima fluidez del tráfico.", "Para garantizar la máxima fluidez, aunque baje la seguridad.", "Para garantizar la máxima seguridad, aunque baje la fluidez."], correcta: 0, explicacion: "Los límites buscan que el tráfico sea seguro y fluido a la vez. La seguridad nunca se sacrifica por la fluidez." },
      { id: "dgt260-04", tema: "factores", pregunta: "¿El consumo de drogas ilegales o de abuso puede alterar la percepción del riesgo?", opciones: ["Sí, la aumenta y el conductor percibe mejor los peligros.", "Sí, la disminuye y el conductor percibe peor los peligros.", "No, no altera la percepción del riesgo."], correcta: 1, explicacion: "Las drogas alteran la atención y el juicio: el conductor no aprecia bien los peligros y reacciona peor." },
      { id: "dgt260-06", tema: "maniobras", pregunta: "Ya ha empezado un adelantamiento y aparecen circunstancias que dificultan terminarlo sin riesgo. ¿Qué debe hacer el conductor?", opciones: ["Aumentar la velocidad para acabar cuanto antes.", "Avisar del peligro al vehículo al que está adelantando para que detenga su marcha.", "Reducir la velocidad y volver a su carril sin estorbar a nadie."], correcta: 2, explicacion: "Si el adelantamiento se complica, lo seguro es frenar un poco y volver a tu carril sin obstaculizar a quien circula en sentido contrario." },
      { id: "dgt260-07", tema: "maniobras", pregunta: "En los lugares donde la señalización no se pueda ver bien por los usuarios a los que afecta, ¿qué está prohibido?", opciones: ["Parar, aunque sí se puede estacionar.", "Estacionar, aunque sí se puede parar.", "Parar y estacionar."], correcta: 2, explicacion: "Si la señal no se ve bien, no se puede saber si hay una prohibición. Por eso en esos lugares está prohibido tanto parar como estacionar." },
      { id: "dgt260-08", tema: "factores", pregunta: "¿Qué le ocurre a un conductor que tiene sueño?", opciones: ["Tarda menos en reaccionar.", "Analiza las situaciones complejas del tráfico en menos tiempo.", "Tarda más en reaccionar."], correcta: 2, explicacion: "El sueño enlentece los reflejos y la capacidad de reacción. Cuando aparezca, para en un lugar seguro y descansa." },
      { id: "dgt260-09", tema: "velocidad", pregunta: "¿Pueden los sistemas de navegación ayudar a controlar la velocidad?", opciones: ["Solo cuando se circula a más de 100 km/h.", "No, no sirven para controlar la velocidad.", "Sí, aunque la principal fuente de información debe ser siempre el velocímetro."], correcta: 2, explicacion: "El GPS puede avisar de los límites, pero el velocímetro del coche es siempre la referencia principal." },
      { id: "dgt260-11", tema: "accidentes", pregunta: "Su turismo se ha quedado atascado en una zona de barro y las ruedas motrices patinan. ¿Cuál es la forma más adecuada de seguir circulando?", opciones: ["Pisar a fondo el acelerador para ganar tracción.", "Preparar un suelo firme colocando material (piedras, trozos de madera...) cerca de las ruedas motrices.", "Empujar el coche de lado hacia una superficie con mejor adherencia."], correcta: 1, explicacion: "Con piedras o madera se crea una base firme para que las ruedas agarren. Acelerar a fondo solo hace que se hundan más. También ayuda aligerar peso o bajar un poco la presión de los neumáticos." },
      { id: "dgt260-12", tema: "seguridad", pregunta: "Si el pasajero de una motocicleta no lleva casco, ¿de quién es la responsabilidad?", opciones: ["Del conductor.", "Del pasajero.", "Del titular del vehículo."], correcta: 0, explicacion: "El conductor de la moto es el responsable de que su pasajero lleve puesto el casco de protección." },
      { id: "dgt260-13", tema: "maniobras", pregunta: "¿Qué precaución puede tomar para evitar el riesgo de atropellar a ciclistas?", opciones: ["Iniciar un adelantamiento cuando se acerca un grupo de ciclistas en sentido contrario.", "Usar señales luminosas para avisar de que va a adelantarlos.", "No hacer señales acústicas (claxon) cerca de ellos."], correcta: 2, explicacion: "Un claxonazo de cerca puede asustar a los ciclistas y hacer que pierdan el control. Es mejor avisar con antelación y adelantar con distancia." },
      { id: "dgt260-14", tema: "seguridad", pregunta: "El seguro obligatorio, ¿cubre los daños del conductor que no tiene la culpa de un accidente?", opciones: ["Sí, los daños personales, pero no los materiales.", "Sí, tanto los daños personales como los materiales.", "No, ni los personales ni los materiales."], correcta: 1, explicacion: "El seguro obligatorio cubre a las víctimas que no tienen culpa, tanto en daños personales como en daños materiales." },
      { id: "dgt260-15", tema: "factores", pregunta: "Si el permiso de conducir tiene un año de antigüedad, ¿cuál es la tasa máxima de alcohol permitida?", opciones: ["0,25 miligramos por litro de aire espirado.", "0,30 miligramos por litro de aire espirado.", "0,15 miligramos por litro de aire espirado."], correcta: 2, explicacion: "Los conductores noveles (con menos de dos años de permiso) tienen el límite más bajo: 0,15 mg/l de aire espirado. Para el resto es 0,25 mg/l." }
    ] },

  { id: "dgt-259", numero: 259, fecha: "2021-10", etiqueta: "Octubre 2021", url: "https://revista.dgt.es/es/test/Test-num-259.shtml",
    preguntas: [
      { id: "dgt259-01", tema: "senales", pregunta: "La señal circular de fondo azul con borde rojo, cruzada por una barra roja diagonal y con el texto «16-31», prohíbe...", opciones: ["Parar solo los días indicados en la señal.", "Parar y estacionar.", "Estacionar desde las 9 horas del día 16 hasta las 9 horas del día 1."], correcta: 2, explicacion: "Es una señal de prohibición de estacionar en el periodo que indica. No prohíbe parar, y el periodo va desde las 9 h del día 16 hasta las 9 h del día 1." },
      { id: "dgt259-03", tema: "velocidad", pregunta: "En una carretera convencional fuera de poblado, ¿cuál es la velocidad máxima que puede alcanzar un turismo al adelantar?", opciones: ["120 km/h.", "110 km/h.", "90 km/h."], correcta: 2, explicacion: "Pregunta corregida: desde el 21 de marzo de 2022 no se puede superar el límite para adelantar. Con el límite de 90 km/h, el turismo debe mantenerse en 90. La respuesta original (110 km/h) está desactualizada." },
      { id: "dgt259-05", tema: "senales", pregunta: "Esta señal de peligro (triángulo con una pendiente del 10 % que desciende hacia la derecha), ¿qué indica?", opciones: ["Peligro por bajada con fuerte pendiente.", "Peligro por subida con fuerte pendiente.", "Zona de frenado de emergencia."], correcta: 0, explicacion: "Avisa de una bajada muy pronunciada: hay que reducir la velocidad antes de empezar y usar una marcha corta para no forzar los frenos.", senal: { forma: "triangulo", simbolo: "10%" } },
      { id: "dgt259-06", tema: "maniobras", pregunta: "En un tramo con una línea continua pintada en el centro de la calzada, ¿está permitido adelantar a un camión que circula despacio?", opciones: ["Sí, porque el camión circula despacio.", "No, porque la línea continua lo prohíbe.", "No, porque la vía no tiene arcén."], correcta: 1, explicacion: "Una línea continua prohíbe invadir el carril contrario para adelantar. La velocidad lenta del camión no cambia esa prohibición." },
      { id: "dgt259-07", tema: "seguridad", pregunta: "Para ahorrar combustible, ¿dónde conviene llevar el equipaje?", opciones: ["En el maletero.", "En la baca (portaequipajes del techo).", "En el maletero o en la baca, indistintamente."], correcta: 0, explicacion: "La baca aumenta la resistencia del aire y, con ella, el consumo. Es mejor llevar el equipaje dentro, en el maletero y bien sujeto." },
      { id: "dgt259-08", tema: "seguridad", pregunta: "Para circular con la mayor seguridad posible, ¿qué debe cumplirse?", opciones: ["El vehículo debe estar en perfecto estado, pero no hace falta que lo esté el conductor.", "El conductor debe estar en perfecto estado, pero no hace falta que lo esté el vehículo.", "Tanto el conductor como el vehículo deben estar en perfecto estado."], correcta: 2, explicacion: "La seguridad depende de las dos cosas: un conductor en condiciones (descansado, sin alcohol ni drogas) y un vehículo en buen estado." },
      { id: "dgt259-09", tema: "alumbrado", pregunta: "Con niebla espesa, ¿qué luces debe usar el conductor de un turismo?", opciones: ["Las antiniebla delanteras y las de emergencia.", "Las antiniebla, las de posición y las de emergencia.", "Las antiniebla, las de posición y las de corto alcance (cruce)."], correcta: 2, explicacion: "Con niebla espesa hay que encender las antiniebla, las de posición y las de cruce para verse y ser visto. Las de emergencia no son para la niebla." },
      { id: "dgt259-10", tema: "prioridad", pregunta: "En un cruce con circulación giratoria que no es una glorieta, ¿a qué vehículos debe ceder el paso?", opciones: ["A los que entran por la izquierda.", "A los que entran por la derecha.", "A los que circulan alrededor de la isleta."], correcta: 1, explicacion: "Como no es una glorieta, rige la regla general de prioridad: se cede el paso a los vehículos que llegan por la derecha." },
      { id: "dgt259-11", tema: "seguridad", pregunta: "Una exposición prolongada a temperaturas altas puede dañar más las gomas de las escobillas del limpiaparabrisas. ¿Cuál es el efecto más común?", opciones: ["Se reblandecen y pierden elasticidad.", "Se endurecen y se agrietan.", "Se dilatan y presionan más el cristal."], correcta: 1, explicacion: "El calor endurece y agrieta las gomas, que pierden eficacia. Conviene limpiarlas a menudo y cambiarlas al menos cada dos años." },
      { id: "dgt259-12", tema: "seguridad", pregunta: "¿Para qué sirve el freno de mano (freno de estacionamiento)?", opciones: ["Para reducir la velocidad del vehículo en ciudad.", "Para inmovilizar el vehículo al estacionarlo.", "Para reducir la velocidad en una vía con pendiente prolongada."], correcta: 1, explicacion: "El freno de mano sirve para mantener el coche quieto cuando está aparcado. No es el freno de uso normal para reducir la velocidad." },
      { id: "dgt259-13", tema: "maniobras", pregunta: "¿Qué debe hacer para avisar de que va a reducir la velocidad de su vehículo de forma notable?", opciones: ["Encender las luces de posición.", "Encender el intermitente izquierdo.", "Pisar varias veces el pedal de freno."], correcta: 2, explicacion: "Pisar el freno varias veces seguidas enciende y apaga las luces de freno y avisa a quien viene detrás de que se frena con intensidad." },
      { id: "dgt259-14", tema: "senales", pregunta: "Si hay dos señales del mismo tipo con indicaciones que parecen contradictorias, ¿cuál tiene prioridad?", opciones: ["La más restrictiva.", "La menos restrictiva.", "La más próxima."], correcta: 0, explicacion: "Cuando dos señales se contradicen, manda la más restrictiva, que es la opción más segura." }
    ] },

  { id: "dgt-258", numero: 258, fecha: "2021-06", etiqueta: "Junio 2021", url: "https://revista.dgt.es/es/test/Test-num-258.shtml",
    preguntas: [
      { id: "dgt258-01", tema: "seguridad", pregunta: "¿Puede un turismo circular con láminas adhesivas o cortinillas solares en las ventanillas traseras?", opciones: ["No, en ningún caso.", "Sí, en todos los casos.", "Solo si lleva dos retrovisores exteriores."], correcta: 2, explicacion: "Las cortinillas en las ventanillas traseras solo se permiten si el coche tiene retrovisores exteriores a ambos lados, para que el conductor pueda ver bien." },
      { id: "dgt258-02", tema: "maniobras", pregunta: "¿Cuándo está permitido estacionar en un túnel?", opciones: ["Cuando está bien iluminado.", "Cuando la calzada tiene dos carriles por sentido.", "Nunca."], correcta: 2, explicacion: "En los túneles está prohibido estacionar: un coche parado puede provocar accidentes y dificultar la llegada de los servicios de emergencia." },
      { id: "dgt258-03", tema: "prioridad", pregunta: "En una intersección con señal de STOP y buena visibilidad, ¿qué debe hacer?", opciones: ["Parar siempre después de cruzar la línea transversal.", "Seguir sin parar, porque no viene ningún vehículo de frente.", "Parar siempre antes de la línea transversal."], correcta: 2, explicacion: "La señal de STOP obliga a parar aunque no venga nadie: hay que detenerse antes de la línea transversal.", senal: { forma: "octogono", simbolo: "STOP" } },
      { id: "dgt258-04", tema: "via", pregunta: "En una calzada de doble sentido sin carriles marcados, ¿por dónde está obligado a circular?", opciones: ["Por el lugar que considere más seguro.", "Por la derecha, lo más cerca posible del borde.", "Por el eje imaginario de la calzada."], correcta: 1, explicacion: "Sin carriles marcados hay que circular por la derecha, pegado al borde derecho, para dejar paso a los vehículos que vienen de frente." },
      { id: "dgt258-05", tema: "velocidad", pregunta: "Si no hay señales que indiquen otra cosa, ¿cuál es la velocidad máxima en una autopista que atraviesa un poblado?", opciones: ["50 km/h, pudiendo superarla en 20 km/h para adelantar.", "80 km/h.", "50 km/h."], correcta: 1, explicacion: "Dentro de poblado, el límite genérico de una autopista o autovía es de 80 km/h, salvo que una señal indique otra cosa." },
      { id: "dgt258-06", tema: "accidentes", pregunta: "Con lluvia intensa, ¿puede una motocicleta sufrir aquaplaning (pérdida de adherencia por el agua)?", opciones: ["No, solo lo sufren los turismos.", "Solo si la moto lleva sidecar.", "Sí, sobre todo si circula a velocidad elevada."], correcta: 2, explicacion: "El agua se acumula bajo los neumáticos y el vehículo puede flotar sobre ella. Puede pasar en cualquier vehículo, también en motos, sobre todo a gran velocidad." },
      { id: "dgt258-07", tema: "senales", pregunta: "Cuando el fondo de una señal de orientación es amarillo, ¿qué indica?", opciones: ["Que se circula por un tramo de vía en obras.", "Que se circula por una vía para automóviles.", "Que se circula por un tramo especialmente peligroso."], correcta: 0, explicacion: "El fondo amarillo en las señales de orientación indica obras o desvíos temporales. Hay que seguir la desviación con precaución." },
      { id: "dgt258-08", tema: "senales", pregunta: "Los paneles de mensaje variable, ¿pueden usarse para dar instrucciones de obligado cumplimiento?", opciones: ["No, son solo informativos.", "Sí.", "No, solo sirven para avisar de posibles peligros."], correcta: 1, explicacion: "Los paneles de mensaje variable son señales de tráfico: si indican una instrucción, como un límite o un cierre, hay que cumplirla." },
      { id: "dgt258-09", tema: "senales", pregunta: "¿Qué indica esta señal de rombo amarillo con borde blanco?", opciones: ["Calzada en la que hay que ceder el paso a los vehículos que llegan por la derecha.", "Vía pública de atención preferente.", "Calzada con prioridad de paso en las intersecciones sobre los vehículos de otra calzada."], correcta: 2, explicacion: "El rombo amarillo indica que tu calle tiene prioridad en los cruces frente a los vehículos de otras calzadas.", senal: { forma: "rombo", simbolo: "" } },
      { id: "dgt258-10", tema: "via", pregunta: "En una vía urbana, ¿cómo deben hacerse las operaciones de carga y descarga?", opciones: ["Dejando la mercancía en la calzada o en zonas peatonales.", "Respetando lo que dispongan las autoridades municipales.", "Por el lado del vehículo más alejado del borde de la calzada."], correcta: 1, explicacion: "Cada ayuntamiento regula dónde y cuándo se puede cargar y descargar en su término municipal." },
      { id: "dgt258-11", tema: "factores", pregunta: "Conducir con los síntomas de una alergia respiratoria, ¿aumenta el riesgo de sufrir un accidente?", opciones: ["Sí, pero solo en primavera por el polen.", "No, el riesgo es igual que sin alergia.", "Sí, porque puede verse alterada la capacidad de conducir con seguridad."], correcta: 2, explicacion: "La alergia puede afectar a la concentración y a los reflejos, sobre todo si tomas medicamentos que dan somnolencia. Consulta a tu médico." },
      { id: "dgt258-12", tema: "via", pregunta: "¿Se consideran obstáculos en la calzada los resaltos situados en los pasos de peatones?", opciones: ["Sí, cuando son metálicos.", "Sí, porque dificultan cruzar el paso de peatones.", "No, siempre que garanticen la seguridad, sobre todo la de los ciclistas."], correcta: 2, explicacion: "Los resaltos no son obstáculos si están bien diseñados y garantizan la seguridad de peatones y ciclistas." },
      { id: "dgt258-13", tema: "maniobras", pregunta: "En una calle residencial, ¿está permitido estacionar?", opciones: ["No, salvo en los lugares señalizados para ello.", "No, salvo por la noche.", "Sí, en cualquier lugar de la vía."], correcta: 0, explicacion: "En una calle residencial solo se puede aparcar en los sitios señalizados para ello." },
      { id: "dgt258-14", tema: "accidentes", pregunta: "Si se produce un incendio dentro de un túnel, ¿qué medida, entre otras, debe adoptar el conductor?", opciones: ["Apartar el vehículo a la derecha para dejar paso a los servicios de emergencia.", "Apagar el motor y quedarse dentro del vehículo.", "Dejar el motor en marcha y salir del túnel."], correcta: 0, explicacion: "Hay que apartarse a la derecha para dejar libre el paso a bomberos y ambulancias, y seguir las indicaciones del túnel." },
      { id: "dgt258-15", tema: "alumbrado", pregunta: "Con lluvia muy intensa, que reduce mucho la visibilidad, ¿se puede circular con la luz antiniebla trasera encendida?", opciones: ["No, solo con niebla densa.", "Sí.", "Sí, aunque su uso es opcional."], correcta: 1, explicacion: "Con lluvia o niebla que reducen mucho la visibilidad, la antiniebla trasera ayuda a que te vean desde detrás." }
    ] },

  { id: "dgt-257", numero: 257, fecha: "2021-03", etiqueta: "Marzo 2021", url: "https://revista.dgt.es/es/test/Test-num-257.shtml",
    preguntas: [
      { id: "dgt257-01", tema: "via", pregunta: "¿Qué es un catadióptrico?", opciones: ["Un dispositivo que refleja la luz que le llega de una fuente luminosa.", "Una placa de matrícula reflectante.", "Un dispositivo de alumbrado del vehículo."], correcta: 0, explicacion: "El catadióptrico es un reflector: devuelve la luz que recibe, así que sirve para que te vean de noche. No es una luz que se encienda." },
      { id: "dgt257-02", tema: "seguridad", pregunta: "¿Puede circular un vehículo cuyo nivel de ruido supere los límites establecidos?", opciones: ["Sí.", "No.", "Solo si circula por vías urbanas."], correcta: 1, explicacion: "Un vehículo que supera los límites de ruido no puede circular: hay que corregir el problema antes de usarlo." },
      { id: "dgt257-04", tema: "factores", pregunta: "En general, ¿los conductores jóvenes valoran peor los riesgos de la circulación?", opciones: ["No.", "Sí, y eso reduce la posibilidad de tener un accidente.", "Sí, y eso aumenta la posibilidad de tener un accidente."], correcta: 2, explicacion: "Por falta de experiencia, los jóvenes tienden a subestimar los riesgos, y por eso tienen más accidentes." },
      { id: "dgt257-05", tema: "factores", pregunta: "Tras tomar somníferos o hipnóticos, ¿qué suele ocurrir con el tiempo de reacción?", opciones: ["Disminuye.", "Aumenta.", "Aumenta el campo visual."], correcta: 1, explicacion: "Los somníferos y los hipnóticos enlentecen los reflejos. No conduzcas si los has tomado." },
      { id: "dgt257-06", tema: "alumbrado", pregunta: "De día, ¿en qué tipo de vía deben las motocicletas llevar encendida la luz de cruce?", opciones: ["En cualquier tipo de vía.", "Solo en vías interurbanas.", "Solo cuando las condiciones meteorológicas sean adversas."], correcta: 0, explicacion: "Las motos deben circular con la luz de cruce encendida durante el día, en cualquier vía, para ser más visibles." },
      { id: "dgt257-07", tema: "accidentes", pregunta: "Un conductor que, pudiendo hacerlo sin riesgo, no se detiene a ayudar a una víctima grave que está desamparada, ¿puede cometer un delito?", opciones: ["Sí, aunque no esté implicado en el accidente.", "No, es un deber moral, pero no legal.", "Sí, solo si estaba implicado en el accidente."], correcta: 0, explicacion: "La omisión del deber de socorro es un delito en el Código Penal. Cualquiera que pueda ayudar sin riesgo debe hacerlo, esté o no implicado." },
      { id: "dgt257-08", tema: "seguridad", pregunta: "En una moto con frenos independientes, ¿dónde se acciona normalmente el freno delantero?", opciones: ["En el manillar, con la mano derecha.", "En el manillar, con la mano izquierda.", "En un pedal, con el pie izquierdo."], correcta: 0, explicacion: "En la mayoría de motos, el freno delantero está en la maneta derecha del manillar." },
      { id: "dgt257-11", tema: "accidentes", pregunta: "Cuando llueve, la visibilidad disminuye, sobre todo si la lluvia es fuerte. ¿Qué precauciones debe tomar?", opciones: ["Aumentar la distancia de seguridad y reducir la velocidad.", "No abrir las ventanillas, para que los cristales no se empañen.", "Circular sobre las marcas blancas longitudinales de la carretera."], correcta: 0, explicacion: "Con lluvia hay que dejar más distancia, bajar la velocidad poco a poco y evitar frenazos. Las marcas blancas pintadas resbalan mucho cuando están mojadas." },
      { id: "dgt257-12", tema: "seguridad", pregunta: "Si viaja con una mascota, ¿en qué lugar del vehículo puede ir para que no interfiera en la conducción?", opciones: ["En el asiento delantero, porque el airbag la protege doblemente.", "Donde no comprometa su seguridad ni la del resto, sujeta con un dispositivo adecuado.", "En los asientos traseros, sujeta con el cinturón de seguridad como un pasajero más."], correcta: 1, explicacion: "Los animales deben ir sujetos con un dispositivo adecuado (arnés o jaula), en un lugar que no moleste al conductor ni ponga en riesgo a nadie." },
      { id: "dgt257-13", tema: "seguridad", pregunta: "En la parte trasera de un vehículo hay una lámina reflectante amarilla rodeada de una franja fluorescente roja. ¿Qué indica?", opciones: ["Que el vehículo, o el conjunto de vehículos, mide más de 12 metros.", "Que el vehículo transporta mercancías peligrosas.", "Que no puede superar los 90 km/h."], correcta: 0, explicacion: "Es la señal de vehículo largo: avisa de que el vehículo, o el conjunto, tiene más de 12 metros de longitud." },
      { id: "dgt257-14", tema: "senales", pregunta: "Esta señal de peligro avisa de la proximidad de...", opciones: ["Un tramo de vía con posible obstrucción en la calzada.", "Un resalto o badén, o un pavimento en mal estado.", "Un tramo de vía con pendientes en subida y en bajada."], correcta: 1, explicacion: "El triángulo con esta silueta avisa de un resalto o badén (una elevación del asfalto). Hay que reducir la velocidad al pasarlo.", senal: { forma: "triangulo", simbolo: "∩" } },
      { id: "dgt257-15", tema: "senales", pregunta: "Esta señal azul indica que...", opciones: ["A su altura puede dar la vuelta hacia la derecha.", "Las únicas direcciones aconsejadas son seguir de frente o girar a la derecha.", "Debe seguir una de las direcciones y sentidos que señalan las flechas."], correcta: 2, explicacion: "Es una señal de obligación: hay que seguir una de las direcciones que marcan las flechas.", senal: { forma: "circulo-azul", simbolo: "↑↱" } }
    ] },

  { id: "dgt-256", numero: 256, fecha: "2020-12", etiqueta: "Diciembre 2020", url: "https://revista.dgt.es/es/test/Test-num-256.shtml",
    preguntas: [
      { id: "dgt256-01", tema: "alumbrado", pregunta: "De noche, ¿están obligados los ciclistas a encender el alumbrado?", opciones: ["Sí.", "No, si llevan puestas prendas reflectantes.", "Solo cuando circulan por vías interurbanas."], correcta: 0, explicacion: "De noche, las bicicletas deben llevar luces. Las prendas reflectantes ayudan, pero no sustituyen a la luz." },
      { id: "dgt256-02", tema: "seguridad", pregunta: "La carga transportada en un turismo no debe...", opciones: ["Descargarse por el lado del coche más cercano al borde de la calzada.", "Sobresalir por la parte trasera más de un 5 % de su longitud.", "Comprometer la estabilidad del vehículo."], correcta: 2, explicacion: "La carga debe ir bien sujeta y repartida. Si compromete la estabilidad del vehículo, no se puede transportar así." },
      { id: "dgt256-03", tema: "velocidad", pregunta: "¿Cómo puede reducir la velocidad de su vehículo?", opciones: ["Solo con el sistema de frenado.", "Solo con el motor.", "Con el sistema de frenado y con el motor a la vez."], correcta: 2, explicacion: "Puedes frenar con el pedal y también ayudarte del motor, por ejemplo soltando el acelerador y reduciendo de marcha." },
      { id: "dgt256-04", tema: "maniobras", pregunta: "En una vía de doble sentido, ¿dónde debe situarse para girar a la izquierda?", opciones: ["Sobre la línea discontinua, invadiendo ligeramente el sentido contrario.", "Junto a la línea discontinua, sin invadir el sentido contrario.", "A la derecha, fuera de la calzada siempre que sea posible."], correcta: 1, explicacion: "Para girar a la izquierda te colocas junto al eje de la calzada, sin invadir el carril contrario, y esperas el hueco para girar." },
      { id: "dgt256-05", tema: "via", pregunta: "En la calzada hay un tramo pintado de azul con el dibujo blanco de una bicicleta. ¿Para quién es ese paso?", opciones: ["Para peatones.", "Para ciclistas.", "Para ciclistas y ciclomotores."], correcta: 1, explicacion: "La franja azul con el símbolo de bicicleta marca un paso reservado para ciclistas." },
      { id: "dgt256-06", tema: "factores", pregunta: "¿La falta de experiencia al volante puede explicar los accidentes de los conductores noveles?", opciones: ["Sí, es una de las causas de los accidentes de los jóvenes.", "No; solo influyen la vía y el vehículo.", "Solo si el conductor novel ha consumido alcohol o drogas."], correcta: 0, explicacion: "La falta de experiencia es una causa importante de accidentes entre noveles, porque aún no saben anticipar los riesgos." },
      { id: "dgt256-07", tema: "accidentes", pregunta: "Hay nieve y solo tiene cadenas para dos ruedas. ¿En qué ruedas deben colocarse?", opciones: ["Siempre en las delanteras.", "Siempre en las motrices.", "Siempre en las traseras."], correcta: 1, explicacion: "Las cadenas van en las ruedas motrices, que son las que transmiten la fuerza del motor y necesitan más agarre." },
      { id: "dgt256-08", tema: "maniobras", pregunta: "En una carretera sin arcén, ¿puede estacionar a la derecha, fuera de la calzada?", opciones: ["Sí, porque está fuera de la calzada.", "No, porque es una vía interurbana.", "Solo si una señal lo permite expresamente."], correcta: 0, explicacion: "Que no haya arcén no impide estacionar fuera de la calzada, siempre que no se invada la vía ni se obstruya el tráfico." },
      { id: "dgt256-09", tema: "accidentes", pregunta: "Si el vehículo queda parado por una avería en un paso a nivel, ¿qué debe hacer el conductor en primer lugar?", opciones: ["Hacer que todos los ocupantes abandonen el vehículo.", "Desconectar los bornes de la batería.", "Colocar una señal de peligro en la vía."], correcta: 0, explicacion: "En un paso a nivel lo primero es poner a salvo a los ocupantes: que salgan del coche y se alejen de la vía." },
      { id: "dgt256-10", tema: "accidentes", pregunta: "Circular en moto bajo una lluvia intensa obliga a...", opciones: ["Circular lo más cerca posible del vehículo que va delante.", "Moderar la velocidad, e incluso detenerse si fuera preciso.", "Llevar encendidas las luces de largo alcance, incluso dentro de poblado."], correcta: 1, explicacion: "Con lluvia intensa hay menos adherencia y menos visibilidad: hay que ir más despacio y, si hace falta, parar en un lugar seguro." },
      { id: "dgt256-11", tema: "accidentes", pregunta: "Fuera de poblado, una autocaravana quiere adelantar a un vehículo pesado. Si sopla un fuerte viento lateral por la izquierda, ¿puede haber riesgo al ir en paralelo?", opciones: ["No, si ambos vehículos tienen el mismo volumen y peso.", "Sí, porque los dos vehículos se empujarían bruscamente hacia la izquierda.", "Sí, por el efecto pantalla: la autocaravana puede aproximarse bruscamente al vehículo pesado."], correcta: 2, explicacion: "Al ir en paralelo, el vehículo grande tapa parte del viento. Al dejar de estar protegida, la autocaravana puede acercarse bruscamente al vehículo pesado. Hay que sujetar el volante con firmeza y no hacer movimientos bruscos." },
      { id: "dgt256-12", tema: "factores", pregunta: "¿El consumo de alcohol afecta al tiempo que tarda el conductor en reaccionar ante una emergencia?", opciones: ["Sí, el tiempo de reacción aumenta.", "Sí, el tiempo de reacción disminuye.", "No, el alcohol no afecta al tiempo de reacción."], correcta: 0, explicacion: "El alcohol alarga el tiempo de reacción y reduce la atención, aunque te sientas bien." },
      { id: "dgt256-14", tema: "via", pregunta: "¿Puede influir el estilo de conducción de una moto en su consumo de combustible?", opciones: ["No, solo depende de la cilindrada.", "No, si se adopta una postura aerodinámica.", "Sí."], correcta: 2, explicacion: "Acelerar bruscamente, frenar en exceso o ir muy rápido aumenta el consumo. Una conducción suave y regular gasta menos." },
      { id: "dgt256-15", tema: "senales", pregunta: "La señal circular roja con las palabras PEAJE y TOLL, ¿qué indica?", opciones: ["La prohibición de detenerse en el peaje.", "La prohibición de pasar por el peaje sin detenerse.", "La prohibición de acceder al peaje."], correcta: 1, explicacion: "En el peaje es obligatorio detenerse: pasar sin parar está prohibido." }
    ] },

  { id: "dgt-255", numero: 255, fecha: "2020-10", etiqueta: "Octubre 2020", url: "https://revista.dgt.es/es/test/Test-num-255.shtml",
    preguntas: [
      { id: "dgt255-01", tema: "alumbrado", pregunta: "La luz antiniebla trasera debe usarse siempre que...", opciones: ["Se circule a una velocidad anormalmente reducida.", "Se circule por carreteras de alta montaña.", "Las condiciones meteorológicas sean especialmente desfavorables."], correcta: 2, explicacion: "La antiniebla trasera se enciende con niebla o lluvia intensa que reducen mucho la visibilidad, para que te vean desde detrás." },
      { id: "dgt255-02", tema: "accidentes", pregunta: "Ante esta señal de peligro por posibles desprendimientos, ¿qué medidas debe adoptar?", opciones: ["Aumentar la atención por posibles piedras u obstáculos en la calzada.", "Acelerar para pasar la zona lo más rápido posible.", "Circular en sentido contrario, con precaución, si hay desprendimientos."], correcta: 0, explicacion: "Hay riesgo de piedras y obstáculos en la calzada: hay que extremar la atención y circular con cuidado.", senal: { forma: "triangulo", simbolo: "🪨" } },
      { id: "dgt255-03", tema: "maniobras", pregunta: "A partir de esta señal (círculo rojo con un camión y un turismo), ¿puede un camión de menos de 3.500 kg de MMA adelantar a otros vehículos?", opciones: ["No, la señal prohíbe adelantar a cualquier vehículo a motor.", "Sí, la prohibición solo afecta a los camiones de más de 3.500 kg de MMA.", "Solo puede adelantar a vehículos de dos ruedas."], correcta: 1, explicacion: "La señal prohíbe adelantar a los camiones de más de 3.500 kg de masa máxima autorizada. Un camión más ligero sí puede adelantar.", senal: { forma: "circulo-rojo", simbolo: "🚛🚗" } },
      { id: "dgt255-04", tema: "via", pregunta: "Este conjunto de bandas blancas paralelas pintadas en la calzada, ¿qué indica?", opciones: ["Que el vehículo debe detenerse siempre.", "Un paso para peatones.", "Que ningún conductor puede entrar con vehículo o animal en esa zona."], correcta: 1, explicacion: "Son las rayas de un paso de peatones: hay que ceder el paso a quien cruza." },
      { id: "dgt255-05", tema: "prioridad", pregunta: "Para incorporarse a la vía principal, un turismo debe cruzar un carril bici bien señalizado. ¿Debe ceder el paso a los ciclistas que circulan por él?", opciones: ["Sí, los ciclistas tienen prioridad de paso.", "No, el turismo tiene prioridad de paso.", "Solo cuando los ciclistas vayan en grupo."], correcta: 0, explicacion: "Al cruzar un carril bici, el vehículo debe ceder el paso a los ciclistas que circulan por él." },
      { id: "dgt255-06", tema: "seguridad", pregunta: "¿Conviene revisar con cierta frecuencia el nivel del líquido del lavaparabrisas?", opciones: ["Sí, para no quedarse sin líquido cuando haga falta.", "Solo en verano, porque el calor lo evapora.", "No, basta con revisarlo antes de pasar la ITV."], correcta: 0, explicacion: "Quedarse sin líquido en mitad de un trayecto es un problema de visibilidad: conviene revisar el nivel con frecuencia." },
      { id: "dgt255-07", tema: "via", pregunta: "En una calzada de doble sentido con dos carriles sin marcas que los separen, ¿por dónde debe circular?", opciones: ["Por el centro de la calzada.", "Por el carril derecho.", "Por cualquiera de los dos, si no vienen vehículos de frente."], correcta: 1, explicacion: "Hay que circular por la derecha de la calzada, aunque no vengan vehículos de frente." },
      { id: "dgt255-08", tema: "velocidad", pregunta: "Con lluvia, ¿es aconsejable aumentar la distancia de seguridad con el vehículo que circula delante?", opciones: ["Sí, porque la distancia de frenado aumenta.", "No, porque la distancia de frenado disminuye.", "Solo en vías rápidas, pero no en ciudad ni en carreteras convencionales."], correcta: 0, explicacion: "Con el suelo mojado el coche tarda más en frenar: hay que dejar más distancia de seguridad." },
      { id: "dgt255-09", tema: "maniobras", pregunta: "¿Cuándo puede adelantar un vehículo dentro de un túnel?", opciones: ["Cuando hay más de un carril en el sentido contrario al suyo.", "Cuando hay más de un carril en su sentido de circulación.", "Cuando hay un carril por sentido y el túnel está bien iluminado."], correcta: 1, explicacion: "Dentro de un túnel solo se puede adelantar si el sentido de circulación propio tiene más de un carril." },
      { id: "dgt255-10", tema: "senales", pregunta: "Esta señal azul muestra tres carriles con flechas: la de la izquierda es oblicua y las otras dos son rectas. ¿Qué indica la flecha de la izquierda?", opciones: ["Obliga a seguir la dirección de la flecha en la próxima intersección.", "Que en el próximo tramo se desvía el carril de la izquierda.", "Que es obligatorio circular por el arcén izquierdo."], correcta: 1, explicacion: "La flecha oblicua indica que el carril de la izquierda se desvía en el próximo tramo: hay que prepararse para cambiar de dirección.", senal: { forma: "cuadrado-azul", simbolo: "↖↑↑" } },
      { id: "dgt255-11", tema: "seguridad", pregunta: "A la entrada y salida del colegio, además de vigilar el entorno, ¿qué precauciones deben tomarse cuando los niños bajan del vehículo?", opciones: ["No abrir las puertas ni bajar hasta que el vehículo esté completamente parado.", "Bajar siempre por la puerta del conductor.", "Bajar por la puerta más alejada del borde de la vía."], correcta: 0, explicacion: "Hay que esperar a que el coche esté totalmente parado y bajar por el lado de la acera, el más cercano al borde de la vía, tras vigilar el entorno." },
      { id: "dgt255-14", tema: "maniobras", pregunta: "Está adelantando y ve que hay peligro. ¿Qué debe hacer?", opciones: ["Acelerar y adelantar lo más rápido posible.", "Reducir la velocidad, señalizar y volver a su carril.", "Pedir ayuda al vehículo al que está adelantando."], correcta: 1, explicacion: "Si aparece un peligro durante el adelantamiento, lo seguro es frenar un poco, avisar con el intermitente y volver a tu carril." },
      { id: "dgt255-15", tema: "maniobras", pregunta: "En una calle de sentido único, sin señales ni marcas que prohíban estacionar, ¿en qué lados está permitido aparcar?", opciones: ["Solo en el lado derecho.", "En ambos lados, tanto el derecho como el izquierdo.", "Solo en el lado izquierdo."], correcta: 1, explicacion: "Si no hay señales ni marcas que lo prohíban, en una calle de sentido único se puede aparcar a ambos lados." }
    ] },

  { id: "dgt-254", numero: 254, fecha: "2020-07", etiqueta: "Julio 2020", url: "https://revista.dgt.es/es/test/Test-num-254.shtml",
    preguntas: [
      { id: "dgt254-01", tema: "senales", pregunta: "¿A qué vehículos de transporte de mercancías prohíbe el paso esta señal (círculo rojo con un camión y «3,5 t»)?", opciones: ["A los de más de 3.500 kg de MMA, solo cuando llevan carga.", "A los de menos de 3.500 kg de MMA.", "A los de más de 3.500 kg de MMA, con carga o sin carga."], correcta: 2, explicacion: "La señal prohíbe el paso a los vehículos de transporte de mercancías de más de 3.500 kg de masa máxima autorizada, lleven o no carga.", senal: { forma: "circulo-rojo", simbolo: "3,5t" } },
      { id: "dgt254-02", tema: "maniobras", pregunta: "Para adelantar a un grupo de ciclistas, un vehículo cruza la línea continua y ocupa el carril contrario. ¿Es correcto su comportamiento?", opciones: ["Sí, si deja al menos 1,5 metros de separación lateral.", "Solo si no hay una señal vertical que prohíba adelantar.", "No, porque en ese tramo el adelantamiento está prohibido."], correcta: 0, explicacion: "Se puede cruzar la línea continua para adelantar a ciclistas si es seguro y se guardan al menos 1,5 metros de separación lateral." },
      { id: "dgt254-03", tema: "accidentes", pregunta: "Si sufre una avería y tiene que bajarse del vehículo, ¿en cuál de estos casos debe ponerse el chaleco reflectante?", opciones: ["Al ocupar el arcén de una vía interurbana.", "Solo al ocupar la calzada o el arcén de autopistas o autovías.", "Al ocupar la calzada de una vía urbana."], correcta: 0, explicacion: "Al bajarse del coche en una vía interurbana (también en autovías y autopistas) hay que usar el chaleco reflectante, aunque estés en el arcén." },
      { id: "dgt254-04", tema: "velocidad", pregunta: "Si entra en una curva a la izquierda a velocidad excesiva, la fuerza centrífuga, ¿puede desplazar el vehículo?", opciones: ["Sí, lo desplaza hacia la izquierda de la calzada.", "Sí, lo desplaza hacia la derecha de la calzada.", "No, la fuerza centrífuga no afecta a la trayectoria."], correcta: 1, explicacion: "La fuerza centrífuga empuja el coche hacia el exterior de la curva. En una curva a la izquierda, eso significa hacia la derecha." },
      { id: "dgt254-05", tema: "accidentes", pregunta: "¿Cómo se llaman los costes de las vidas perdidas, de la capacidad productiva y del sufrimiento físico y psicológico que causa un accidente de tráfico?", opciones: ["Costes sanitarios.", "Costes materiales.", "Costes humanos."], correcta: 2, explicacion: "Los costes humanos son los que no se miden solo en dinero: vidas, pérdida de capacidad y sufrimiento." },
      { id: "dgt254-06", tema: "seguridad", pregunta: "Si todos sus elementos funcionan bien, ¿qué sistema de seguridad pasiva evita el efecto submarino en un accidente?", opciones: ["El airbag.", "El reposacabezas.", "El cinturón de seguridad."], correcta: 2, explicacion: "El cinturón sujeta el cuerpo al asiento y evita que se deslice hacia abajo (efecto submarino). El airbag lo complementa, pero no lo sustituye." },
      { id: "dgt254-07", tema: "via", pregunta: "¿Quién se considera peatón?", opciones: ["Quien, sin ser conductor, camina por las vías públicas.", "Quien tiene a su cargo uno o varios animales.", "Quien circula en bicicleta."], correcta: 0, explicacion: "Es peatón quien va a pie por la vía pública sin conducir ningún vehículo." },
      { id: "dgt254-08", tema: "factores", pregunta: "¿El consumo de drogas de abuso o ilegales afecta a la seguridad vial?", opciones: ["No, en absoluto.", "Sí, porque altera de forma importante las capacidades del conductor.", "Solo si el conductor no está acostumbrado a consumirlas."], correcta: 1, explicacion: "Las drogas alteran la atención, los reflejos y la percepción del peligro, y eso pone en riesgo a todos." },
      { id: "dgt254-09", tema: "factores", pregunta: "Durante la conducción, ¿en qué horas aparece especialmente el sueño?", opciones: ["Las últimas horas de la mañana.", "La madrugada y las primeras horas de la tarde.", "Las últimas horas de la tarde y las primeras de la mañana."], correcta: 1, explicacion: "Son las horas en las que el cuerpo pide descanso con más fuerza. Si notas sueño, para a descansar." },
      { id: "dgt254-10", tema: "seguridad", pregunta: "En un turismo con cinco plazas autorizadas, incluida la del conductor, ¿se pueden llevar seis personas?", opciones: ["No.", "Sí, mientras no se supere la masa máxima autorizada del vehículo.", "Solo si al menos uno de los ocupantes es menor de edad."], correcta: 0, explicacion: "No se pueden llevar más personas que plazas autorizadas, aunque no se supere el peso máximo del vehículo." },
      { id: "dgt254-12", tema: "via", pregunta: "A los peatones que usan monopatines o patines, ¿qué les está prohibido en cualquier caso?", opciones: ["Ser arrastrados por otros vehículos.", "Circular por el arcén de una travesía.", "Circular a paso de persona por las aceras."], correcta: 0, explicacion: "Un peatón con patines no puede dejarse remolcar por un vehículo. Los patinetes eléctricos (VMP) tienen su propia normativa." },
      { id: "dgt254-13", tema: "factores", pregunta: "Los efectos secundarios de los medicamentos que alteran la capacidad de conducir, ¿se notan igual en todas las personas?", opciones: ["Solo si el tratamiento se alarga en el tiempo.", "Sí, son idénticos para todas las personas.", "No, pueden variar según factores como la edad o el estado físico."], correcta: 2, explicacion: "Cada persona reacciona de forma distinta a un medicamento. La edad o el estado físico influyen, así que consulta siempre con tu médico o farmacéutico." },
      { id: "dgt254-15", tema: "factores", pregunta: "¿Es peligroso introducir un destino en un navegador GPS mientras se conduce?", opciones: ["Solo si el navegador no está integrado en el vehículo.", "No, porque es una ayuda para conducir con más seguridad.", "Sí, porque distrae al conductor."], correcta: 2, explicacion: "Programar el GPS con el coche en marcha distrae la vista y la mente. Hay que hacerlo parado." }
    ] },

  { id: "dgt-253", numero: 253, fecha: "2020-06", etiqueta: "Junio 2020", url: "https://revista.dgt.es/es/test/Test-num-253.shtml",
    preguntas: [
      { id: "dgt253-01", tema: "accidentes", pregunta: "Por una emergencia, un turismo queda inmovilizado en la calzada. ¿Debe señalizarlo con el dispositivo de peligro (triángulo o baliza V-16), aunque tenga encendidas las luces?", opciones: ["No, salvo que esté fuera de poblado.", "Solo debe encender la luz de emergencia y, si procede, las luces de posición.", "Sí, aunque tenga encendidas la luz de emergencia, las de posición o ambas."], correcta: 2, explicacion: "Pregunta corregida: la señalización es obligatoria aunque haya luces encendidas. Desde el 1 de enero de 2026 la baliza V-16 conectada es obligatoria y sustituye al triángulo; la respuesta original hablaba solo del triángulo." },
      { id: "dgt253-02", tema: "senales", pregunta: "Ante esta señal de peligro (triángulo con un coche accidentado dentro), ¿qué indica?", opciones: ["Peligro por la cercanía de una zona con fuerte viento lateral.", "Peligro por la cercanía de un tramo con pavimento deslizante por hielo.", "Peligro por la cercanía de un vehículo accidentado que obstruye la calzada."], correcta: 2, explicacion: "Avisa de que, más adelante, hay un vehículo accidentado que puede estar bloqueando la calzada. Hay que reducir y extremar la atención.", senal: { forma: "triangulo", simbolo: "🚗" } },
      { id: "dgt253-03", tema: "via", pregunta: "En las vías de tres calzadas, ¿cómo se utilizan normalmente las calzadas laterales?", opciones: ["En sentido único, aunque puede habilitarse algún carril para el sentido contrario.", "En los dos sentidos de circulación.", "En sentido único, siempre que el tráfico sea fluido."], correcta: 0, explicacion: "Las calzadas laterales suelen ser de sentido único, aunque a veces se habilita algún carril para el otro sentido." },
      { id: "dgt253-04", tema: "accidentes", pregunta: "Cuando sopla un fuerte viento lateral, ¿qué debe hacer?", opciones: ["Reducir la velocidad y corregir las desviaciones leves de la dirección.", "Aumentar la velocidad para compensar la fuerza del viento.", "El riesgo baja, porque el viento impide que el coche se desvíe."], correcta: 0, explicacion: "Con viento lateral conviene ir más despacio, sujetar el volante con firmeza y corregir las desviaciones con suavidad." },
      { id: "dgt253-05", tema: "seguridad", pregunta: "¿Cuándo hay que cambiar las escobillas del limpiaparabrisas?", opciones: ["Cada dos años, obligatoriamente.", "Cuando las gomas estén dañadas.", "Siempre antes de pasar la inspección técnica."], correcta: 1, explicacion: "Hay que cambiarlas cuando las gomas estén gastadas, agrietadas o no limpien bien. No existe una fecha obligatoria." },
      { id: "dgt253-06", tema: "senales", pregunta: "Esta señal azul, ¿prohíbe girar en la próxima intersección?", opciones: ["Sí, porque debo seguir la dirección y el sentido que marca la flecha.", "No, solo prohíbe el cambio de sentido.", "No, solo indica que la vía es de sentido único."], correcta: 0, explicacion: "Es una señal de obligación: hay que seguir recto en la dirección de la flecha, sin girar en ese cruce.", senal: { forma: "circulo-azul", simbolo: "↑" } },
      { id: "dgt253-07", tema: "prioridad", pregunta: "¿Tiene prioridad de paso una ambulancia que circula con las señales luminosas apagadas?", opciones: ["No.", "Solo en vías urbanas.", "Sí, en cualquier tipo de vía."], correcta: 0, explicacion: "La preferencia de paso de una ambulancia solo existe cuando lleva en funcionamiento sus señales luminosas y acústicas." },
      { id: "dgt253-08", tema: "prioridad", pregunta: "Un vehículo va a incorporarse a la circulación. ¿Cuándo debe ceder el paso?", opciones: ["Solo cuando entra desde la izquierda.", "Siempre.", "Solo cuando entra desde la derecha."], correcta: 1, explicacion: "Quien se incorpora a la circulación desde una vía lateral o un estacionamiento debe ceder el paso siempre a los vehículos que circulan." },
      { id: "dgt253-09", tema: "velocidad", pregunta: "Circula con su turismo por una carretera convencional fuera de poblado, sin señales que indiquen otro límite. ¿Cuál es la velocidad máxima?", opciones: ["90 km/h.", "100 km/h.", "80 km/h."], correcta: 0, explicacion: "En carreteras convencionales fuera de poblado, el límite general para turismos es de 90 km/h, salvo que una señal indique otro." },
      { id: "dgt253-11", tema: "seguridad", pregunta: "¿Por qué es aconsejable cambiar periódicamente el aceite del motor?", opciones: ["Porque, si está en buen estado, el motor se conserva mejor y las piezas se desgastan menos.", "Porque con el tiempo se vuelve más espeso y no circula bien entre las piezas.", "Porque con el uso pierde mucho volumen y hay que reponerlo constantemente."], correcta: 0, explicacion: "El aceite se degrada con el uso y pierde sus propiedades. Cambiarlo a tiempo protege el motor. Sigue las indicaciones del fabricante." },
      { id: "dgt253-13", tema: "prioridad", pregunta: "Si se pone en verde un semáforo en un cruce donde también hay una señal de STOP, ¿qué debe hacer?", opciones: ["Obedecer la señal de STOP.", "Obedecer al semáforo, que tiene prioridad sobre la señal de STOP.", "Obedecer al semáforo, pero ceder el paso igualmente."], correcta: 1, explicacion: "Las indicaciones del semáforo prevalecen sobre las señales de STOP: con la luz verde puedes seguir." },
      { id: "dgt253-14", tema: "maniobras", pregunta: "Si el coche tiene cambio manual y aparca en una calle en subida, ¿cómo debe hacerlo?", opciones: ["Con el freno de estacionamiento puesto y primera marcha.", "Con el freno de estacionamiento puesto y marcha atrás.", "Basta con poner el freno de estacionamiento."], correcta: 0, explicacion: "Para aparcar en subida con cambio manual, pon el freno de mano y engrana primera: así el coche no puede rodar hacia atrás." },
      { id: "dgt253-15", tema: "maniobras", pregunta: "En una calzada de dos sentidos con tres carriles, si quiere girar a la izquierda, ¿dónde debe colocarse?", opciones: ["En el carril central.", "En el arcén derecho.", "En el carril izquierdo."], correcta: 0, explicacion: "En una calzada de dos sentidos con tres carriles, el central es el que se usa para girar a la izquierda. Ahí te colocas y esperas el hueco." }
    ] }
]);
